import { auth } from "@/auth";
import { prisma } from "@/lib/db/prisma";
import { signOut } from "@/auth";

export default async function DashboardPage() {
  const session = await auth();
  const business = await prisma.business.findUniqueOrThrow({ where: { id: session!.user.businessId }, select: { businessName: true, ownerName: true } });
  return <main className="min-h-screen bg-slate-50"><header className="border-b border-slate-200 bg-white"><div className="mx-auto flex max-w-6xl items-center justify-between px-6 py-4"><span className="font-bold">payproof</span><form action={async () => { "use server"; await signOut({ redirectTo: "/" }); }}><button className="text-sm font-semibold text-slate-600">Log out</button></form></div></header><section className="mx-auto max-w-6xl px-6 py-14"><p className="font-semibold text-blue-600">{business.businessName}</p><h1 className="mt-2 text-4xl font-bold tracking-tight">Welcome, {business.ownerName}.</h1><div className="mt-10 rounded-2xl border border-slate-200 bg-white p-8 shadow-sm"><h2 className="text-xl font-bold">Your workspace is ready</h2><p className="mt-2 max-w-xl leading-7 text-slate-600">Create your first customer, product, and order next. Payment records will only be marked paid after a verified provider transaction.</p></div></section></main>;
}
